-- ============================================================
-- Digital PC Builder - MySQL / MariaDB schema + sample data
-- Import with phpMyAdmin (XAMPP) or:  mysql -u root < backend/database.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS digital_pc_builder
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE digital_pc_builder;

DROP TABLE IF EXISTS builds;
DROP TABLE IF EXISTS components;

-- Hardware catalog. Category-specific technical and compatibility
-- attributes (socket, form factor, wattage, ...) live in the `specs`
-- JSON document so every category can keep its own structure.
CREATE TABLE components (
  id            VARCHAR(40)   NOT NULL PRIMARY KEY,
  category      ENUM('cpu','gpu','motherboard','ram','storage','psu','case','cooler') NOT NULL,
  name          VARCHAR(120)  NOT NULL,
  brand         VARCHAR(60)   NOT NULL,
  price         DECIMAL(10,2) NOT NULL COMMENT 'Sample estimated price in Philippine pesos (PHP)',
  image         VARCHAR(255)  NOT NULL,
  release_year  SMALLINT      NULL,
  specs         LONGTEXT      NOT NULL COMMENT 'JSON object of specifications',
  price_source  LONGTEXT      NULL COMMENT 'JSON: where the price came from (store, listing, status, date checked)',
  created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_category (category),
  INDEX idx_brand (brand)
) ENGINE=InnoDB;

-- Saved user builds. `parts` is a JSON object that maps each category
-- to a component id (storage maps to an array of ids).
CREATE TABLE builds (
  id           INT UNSIGNED  NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name         VARCHAR(100)  NOT NULL,
  usage_type   ENUM('gaming','programming','video','rendering','general') NOT NULL DEFAULT 'gaming',
  budget       DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT 'PHP',
  resolution   ENUM('1080p','1440p','4k') NOT NULL DEFAULT '1440p',
  notes        VARCHAR(500)  NOT NULL DEFAULT '',
  parts        LONGTEXT      NOT NULL COMMENT 'JSON: {"cpu":"id", ..., "storage":["id"]}',
  total_price  DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT 'PHP',
  created_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

